<?php $form_values=$form_values ?? []; $esc=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}; ?>
<label>Customer <span aria-hidden="true">*</span><select name="customer_id" data-bm-select data-bm-customer required><option value="">Choose a customer</option><?php foreach($customers as $customer): ?><option value="<?= (int)$customer->id; ?>" <?= (int)($form_values['customer_id'] ?? 0)===(int)$customer->id?'selected':''; ?>><?= $esc($customer->customer_name); ?></option><?php endforeach; ?></select></label>
<label>Customer site<select name="site_id" data-bm-select data-bm-site><option value="">Customer primary address</option><?php foreach($sites as $site): ?><option data-customer="<?= (int)$site->customer_id; ?>" value="<?= (int)$site->id; ?>" <?= (int)($form_values['site_id'] ?? 0)===(int)$site->id?'selected':''; ?>><?= $esc($site->site_name ?: $site->address); ?></option><?php endforeach; ?></select></label>
<label>Responsible team member<select name="assigned_user_id" data-bm-select><option value="">Unassigned</option><?php foreach($staff as $member): ?><option value="<?= (int)$member->id; ?>" <?= (int)($form_values['assigned_user_id'] ?? 0)===(int)$member->id?'selected':''; ?>><?= $esc($member->username); ?></option><?php endforeach; ?></select></label>
